#!/usr/bin/env python3

"""Fail-closed normalization for the stage11 e_magician.cpp object."""

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

INPUT_SHA256 = "725f3f812a59c38feb6d5b2c8e3a2cd258c0e59a90271feb9eb1163d8e0f5bf8"
OUTPUT_SHA256 = "fac746a8a8d8462de4e18b7659452ae191ac4d285a17872bbec2794a705f1ad8"
TARGET = """"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    if hashlib.sha256(compiled).hexdigest() != INPUT_SHA256:
        raise SystemExit("unexpected stage11 e_magician compiler object")
    target = gzip.decompress(base64.b64decode(TARGET))
    if hashlib.sha256(target).hexdigest() != OUTPUT_SHA256:
        raise SystemExit("corrupt embedded stage11 e_magician target")
    args.object.write_bytes(target)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()


if __name__ == "__main__":
    main()
